import React from 'react';
import styled from 'styled-components';

const ProjectsSection = styled.section`
  max-width: 1100px;
  margin: 0 auto;
  padding: 6rem 1.5rem 3rem 1.5rem;
  color: #fff;
`;

const Heading = styled.h2`
  font-size: 2.5rem;
  font-weight: 800;
  margin-bottom: 2.5rem;
  color: #fff;
`;

const Grid = styled.div`
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
  gap: 2.5rem;
`;

const Card = styled.div`
  background: #111;
  border-radius: 1.25rem;
  padding: 2rem 1.5rem;
  box-shadow: 0 2px 16px rgba(0,0,0,0.12);
  transition: transform 0.18s, box-shadow 0.18s, filter 0.18s;
  filter: grayscale(1);
  &:hover, &:focus {
    transform: translateY(-6px) scale(1.03);
    box-shadow: 0 6px 32px rgba(0,0,0,0.18);
    filter: grayscale(0.2);
  }
`;

const ProjectTitle = styled.h3`
  font-size: 1.4rem;
  font-weight: 700;
  margin-bottom: 0.75rem;
  color: #fff;
`;

const Description = styled.p`
  color: #aaa;
  font-size: 1.05rem;
  margin-bottom: 1.5rem;
`;

const Links = styled.div`
  display: flex;
  gap: 1.25rem;
`;

const Link = styled.a`
  color: #fff;
  font-weight: 600;
  text-decoration: underline;
  opacity: 0.85;
  transition: opacity 0.18s;
  &:hover, &:focus {
    opacity: 1;
  }
`;

const projects = [
  {
    title: 'Minimal Blog Platform',
    description: 'A clean, fast blog platform built with React and styled-components.',
    live: '#',
    github: '#',
  },
  {
    title: 'Portfolio Website',
    description: 'This portfolio site, showcasing modern frontend best practices.',
    live: '#',
    github: '#',
  },
  {
    title: 'UI Component Library',
    description: 'Reusable, accessible React UI components with a focus on minimalism.',
    live: '#',
    github: '#',
  },
];

const Projects = () => (
  <ProjectsSection id="projects">
    <Heading>Projects</Heading>
    <Grid>
      {projects.map(({ title, description, live, github }) => (
        <Card key={title}>
          <ProjectTitle>{title}</ProjectTitle>
          <Description>{description}</Description>
          <Links>
            <Link href={live} target="_blank" rel="noopener noreferrer">Live</Link>
            <Link href={github} target="_blank" rel="noopener noreferrer">GitHub</Link>
          </Links>
        </Card>
      ))}
    </Grid>
  </ProjectsSection>
);

export default Projects;
